questions.solution:
function evaluateBinaryString(str) {
  if (!str || str.length === 0) return -1;
  let res = parseInt(str[0], 10);
  for (let i = 1; i < str.length; i += 2) {
    const op = str[i];
    const val = parseInt(str[i + 1], 10);
    if (op === 'A') res = res & val;
    else if (op === 'B') res = res | val;
    else if (op === 'C') res = res ^ val;
  }
  return res;
}

questions.javaSolution:
import java.util.*;
import java.io.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String str = sc.next().trim();
            System.out.println(evaluate(str));
        }
    }

    public static int evaluate(String str) {
        if (str == null || str.isEmpty()) return -1;
        int res = str.charAt(0) - '0';
        for (int i = 1; i < str.length(); i += 2) {
            char op = str.charAt(i);
            int nextVal = str.charAt(i + 1) - '0';
            if (op == 'A') {
                res = res & nextVal;
            } else if (op == 'B') {
                res = res | nextVal;
            } else if (op == 'C') {
                res = res ^ nextVal;
            }
        }
        return res;
    }
}

