function minHousesForRats(r, unit, arr) {
  if (!arr || arr.length === 0) return -1;
  const totalNeeded = r * unit;
  let accumulated = 0;
  for (let i = 0; i < arr.length; i++) {
    accumulated += arr[i];
    if (accumulated >= totalNeeded) return i + 1;
  }
  return 0;
}

