function countSuperiorElements(arr) {
  if (!arr || arr.length === 0) return 0;
  let count = 0;
  let maxFromRight = -Infinity;
  for (let i = arr.length - 1; i >= 0; i--) {
    if (arr[i] > maxFromRight) {
      count++;
      maxFromRight = arr[i];
    }
  }
  return count;
}

