function differenceOfSum(n, m) {
  let sumDiv = 0, sumNonDiv = 0;
  for (let i = 1; i <= m; i++) {
    if (i % n === 0) sumDiv += i;
    else sumNonDiv += i;
  }
  return sumNonDiv - sumDiv;
}

