function largeSmallSum(arr) {
  if (!arr || arr.length <= 3) return 0;
  const even = [], odd = [];
  for (let i = 0; i < arr.length; i++) {
    if (i % 2 === 0) even.push(arr[i]);
    else odd.push(arr[i]);
  }
  even.sort((a, b) => a - b);
  odd.sort((a, b) => a - b);
  const secondLargestEven = even[even.length - 2];
  const secondSmallestOdd = odd[1];
  return secondLargestEven + secondSmallestOdd;
}

