function transformSum(nums) {
  let totalSum = 0;
  for (let i = 0; i < nums.length; i++) {
    let val = nums[i] - ((i % 7) * 3);
    if (nums[i] % 11 === 0) {
      val += Math.floor(nums[i] / 11);
    }
    totalSum += val;
  }
  return totalSum;
}

