import java.util.Scanner;

public class Solution {
    public static long calculateEqSum(long x) {
        String s = Long.toString(x);
        long sum = 0;
        long currentPrefix = 0;
        for (int i = 0; i < s.length(); i++) {
            currentPrefix = currentPrefix * 10 + (s.charAt(i) - '0');
            sum += currentPrefix;
        }
        return sum;
    }

    public static int countEqSumGreaterThanN(long n) {
        int count = 0;
        for (long x = n - 1; x >= 1; x--) {
            if (calculateEqSum(x) > n) {
                count++;
            } else {
                if (n - x > 1000) break;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLong()) {
            long n = sc.nextLong();
            System.out.println(countEqSumGreaterThanN(n));
        }
    }
}

