function combineFirstLast(s) {
  let left = 0, right = s.length - 1;
  let res = "";
  while (left <= right) {
    if (left === right) {
      res += s[left];
    } else {
      res += s[left] + s[right];
    }
    left++;
    right--;
  }
  return res;
}

