import java.util.Scanner;

public class Solution {
    public static int maxExponentOf2(int a, int b) {
        int maxExp = -1;
        int bestNum = a;
        for (int i = a; i <= b; i++) {
            int num = i;
            int exp = 0;
            while (num > 0 && num % 2 == 0) {
                exp++;
                num /= 2;
            }
            if (exp > maxExp) {
                maxExp = exp;
                bestNum = i;
            }
        }
        return bestNum;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            System.out.println(maxExponentOf2(a, b));
        }
    }
}

