            } else {
                odd.add(list.get(i));
            }
        }
        Collections.sort(even);
        Collections.sort(odd);
        int secondLargestEven = even.get(even.size() - 2);
        int secondSmallestOdd = odd.get(1);
        System.out.println(secondLargestEven + secondSmallestOdd);
    }
}

