public class Solution {
    public static int minHours(int t) {
        int minHours = Integer.MAX_VALUE;
        for (int k = 1; k <= t; k++) {
            int jumps = k - 1;
            int collections = (t + k - 1) / k;
            int total = jumps + collections;
            if (total < minHours) {
                minHours = total;
            }
            if (k > t / k + 5) break;
        }
        return minHours;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int t = sc.nextInt();
            System.out.println(minHours(t));
        }
    }
}

