public class Solution {
    public static int removeStudents(int[] marks) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int m : marks) freq.put(m, freq.getOrDefault(m, 0) + 1);

        List<Integer> distinct = new ArrayList<>(freq.keySet());
        if (distinct.size() < 2) return 0;

        Collections.sort(distinct, Collections.reverseOrder());
        int top1 = distinct.get(0);
        int top2 = distinct.get(1);

        int removed = (freq.get(top1) - 1) + (freq.get(top2) - 1);
        return removed;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            int[] marks = new int[n];
            for (int i = 0; i < n; i++) marks[i] = sc.nextInt();
            System.out.println(removeStudents(marks));
        }
    }
}

