import java.util.*;

public class Solution {
    public static List<String> mostFrequentCombination(String s) {
        String[] words = s.trim().split("\\s+");
        Map<String, Integer> freq = new LinkedHashMap<>();
        for (String word : words) {
            if (word.isEmpty()) continue;
            String combo = "" + word.charAt(0) + word.charAt(word.length() - 1);
            freq.put(combo, freq.getOrDefault(combo, 0) + 1);
        }
        if (freq.isEmpty()) return Collections.emptyList();
        int maxFreq = Collections.max(freq.values());
        List<String> result = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : freq.entrySet()) {
            if (entry.getValue() == maxFreq) {
                result.add(entry.getKey());
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String s = sc.nextLine();
            List<String> res = mostFrequentCombination(s);
            System.out.println(String.join(" ", res));
        }
    }
}

